59	/****************************************************************************
60	 * Name: test_read_hw_feature
61	 *
62	 * Description:
63	 *   Test reading GMAC hardware feature register to verify base address.
64	 *
65	 ****************************************************************************/
66	
67	static int test_read_hw_feature(uintptr_t gmac_base)
68	{
69	  uint32_t feat0 = getreg32(gmac_base + GMAC_HW_FEATURE0);
70	
71	  printf("HW_FEATURE0 = 0x%08X\n", feat0);
72	  printf("  MII(10/100M): %s\n", (feat0 & (1 << 0)) ? "YES" : "NO");
73	
74	  if (feat0 == 0x00000000 || feat0 == 0xFFFFFFFF)
75	    {
76	      printf("FAIL: Invalid value, base address wrong?\n");
77	      return -1;
78	    }
79	
80	  printf("PASS\n");
81	  return 0;
82	}
