122	/****************************************************************************
123	 * Private Functions - Step 3: EPHY Reset + MDIO Read PHY ID
124	 ****************************************************************************/
125	
126	/****************************************************************************
127	 * Name: ephy_hardware_reset
128	 *
129	 * Description:
130	 *   Perform EPHY hardware reset sequence.
131	 *   Source: dwmac-cvitek.c:46-117
132	 *
133	 ****************************************************************************/
134	
135	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
136	{
137	  /* Select APB interface */
138	
139	  putreg32(0x0001, phy_top + 0x4);
140	
141	  /* Release shutdown */
142	
143	  putreg32(0x0900, phy_top);
144	
145	  /* Release dig_rst_n */
146	
147	  putreg32(0x0904, phy_top);
148	
149	  /* Switch to Page 5 */
150	
151	  putreg32(0x0500, phy_base + 0x7c);
152	
153	  /* ANA_PD */
154	
155	  putreg32(0x0c00, phy_base + 0x40);
156	
157	  /* ANA_EN */
158	
159	  putreg32(0x0c7e, phy_base + 0x40);
160	  up_mdelay(1);
161	
162	  /* Release ana_rst_n */
163	
164	  putreg32(0x0906, phy_top);
165	  putreg32(0x0500, phy_base + 0x7c);
166	
167	  /* Set PHY ID */
168	
169	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
170	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
171	
172	  /* Switch back to MDIO control */
173	
174	  putreg32(0x0000, phy_top + 0x4);
175	  up_mdelay(10);
176	}
