499	/****************************************************************************
500	 * Private Functions - Step 6: ISR + RX Receive
501	 ****************************************************************************/
502	
503	/****************************************************************************
504	 * Name: sg2000_eth_isr
505	 *
506	 * Description:
507	 *   Interrupt service routine.
508	 *   Source: dwmac4_lib.c:141-184
509	 *
510	 ****************************************************************************/
511	
512	static int sg2000_eth_isr(int irq, void *context, void *arg)
513	{
514	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
515	  uintptr_t base = priv->gmac_base;
516	  uintptr_t dma = base + DMA_CHAN_BASE;
517	  uint32_t status;
518	  uint32_t intr_en;
519	  uint32_t mac;
520	
521	  mac = getreg32(base + GMAC_INT_STATUS);
522	  if (mac)
523	    {
524	      putreg32(mac, base + GMAC_INT_STATUS);
525	    }
526	
527	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
528	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
529	
530	  if (!status)
531	    {
532	      return OK;
533	    }
534	
535	  /* W1C clear */
536	
537	  putreg32(status, dma + DMA_CHAN_STATUS);
538	
539	  if (status & DMA_STATUS_NIS)
540	    {
541	      if (status & DMA_STATUS_RI)
542	        {
543	          netdev_rx_ready(&priv->dev);
544	        }
545	
546	      if (status & DMA_STATUS_TI)
547	        {
548	          /* TX complete */
549	        }
550	    }
551	
552	  if (status & DMA_STATUS_AIS)
553	    {
554	      printf("!! DMA Abnormal: 0x%08X\n", status);
555	
556	      if (status & DMA_STATUS_RBU)
557	        {
558	          printf("   RX Buf Unavailable\n");
559	        }
560	
561	      if (status & DMA_STATUS_TPS)
562	        {
563	          printf("   TX Stopped\n");
564	        }
565	
566	      if (status & DMA_STATUS_FBE)
567	        {
568	          printf("   Fatal Bus Error\n");
569	        }
570	    }
571	
572	  return OK;
573	}
