575	/****************************************************************************
576	 * Name: sg2000_eth_rx
577	 *
578	 * Description:
579	 *   Receive a packet from DMA ring.
580	 *
581	 ****************************************************************************/
582	
583	static int sg2000_eth_rx(struct sg2000_eth_priv_s *priv)
584	{
585	  struct sg2000_dma_desc_s *desc = &priv->rx_desc[priv->rx_cur];
586	  uint32_t status;
587	  int len;
588	
589	  if (desc->des0 & DESC_OWN)
590	    {
591	      return 0;  /* DMA still owns it */
592	    }
593	
594	  status = desc->des0;
595	
596	  if (status & RX_DESC_ES)
597	    {
598	      goto refill;  /* Error packet, discard */
599	    }
600	
601	  len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - 4;  /* Remove FCS */
602	
603	  if (len > CONFIG_NET_ETH_PKTSIZE)
604	    {
605	      goto refill;
606	    }
607	
608	  memcpy(priv->dev.d_buf, priv->rx_buf[priv->rx_cur], len);
609	  priv->dev.d_len = len;
610	
611	refill:
612	
613	  /* Return descriptor to DMA */
614	
615	  desc->des0 = DESC_OWN;
616	  desc->des1 = RX_BUF_SIZE;
617	
618	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
619	
620	  rx_doorbell(priv);
621	
622	  return (priv->dev.d_len > 0) ? 1 : 0;
623	}
