717	/****************************************************************************
718	 * Name: sg2000_eth_rmac
719	 *
720	 * Description:
721	 *   Called to receive packets (poll mode).
722	 *
723	 ****************************************************************************/
724	
725	static int sg2000_eth_rmac(struct net_driver_s *dev)
726	{
727	  struct sg2000_eth_priv_s *priv =
