#ifndef __VENDOR_SG2000_SG2000_ETH_H
#define __VENDOR_SG2000_SG2000_ETH_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/net/netdev_lowerhalf.h>
#include <stdint.h>

#include "hardware/sg2000_gmac.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SG2000_GMAC_BASE          0x04070000

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* DWMAC4 Enhanced Descriptor (16 bytes) */

struct sg2000_dma_desc_s
{
  uint32_t des0;  /* Status / OWN */
  uint32_t des1;  /* Buffer size */
  uint32_t des2;  /* Buffer address */
  uint32_t des3;  /* Next descriptor / reserved */
};

/* Driver private data.
 * The netdev_lowerhalf_s MUST be the first member so we can cast between
 * the two structures.
 */

struct sg2000_eth_priv_s
{
  /* This holds the information visible to the OpenVela network stack.
   * MUST be first.
   */

  struct netdev_lowerhalf_s dev;

  uintptr_t gmac_base;              /* GMAC register base */
  uintptr_t phy_base;               /* EPHY register base */
  uintptr_t phy_top;                /* EPHY Top register base */

  /* DMA descriptors and buffers */

  struct sg2000_dma_desc_s *tx_desc;
  struct sg2000_dma_desc_s *rx_desc;
  uint8_t *tx_buf[TX_RING_SIZE];
  uint8_t *rx_buf[RX_RING_SIZE];

  uint32_t tx_desc_phys;            /* TX descriptor physical address */
  uint32_t rx_desc_phys;            /* RX descriptor physical address */

  unsigned int tx_cur;              /* Current TX position */
  unsigned int tx_dirty;            /* TX clean position */
  unsigned int rx_cur;              /* Current RX position */

  uint8_t mac_addr[6];
  int irq;
  int link_up;                      /* 1 = link up, 0 = down */
  int speed;                        /* 10 or 100 */
  int duplex;                       /* 1 = full, 0 = half */

  /* TX tracking: we maintain a queue of pkts being sent */

  FAR netpkt_t *tx_pkt[TX_RING_SIZE]; /* TX packets in flight */
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_initialize
 *
 * Description:
 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
 *   network stack using the netdev_lowerhalf_s architecture.
 *
 * Input Parameters:
 *   None
 *
 * Returned Value:
 *   OK on success; Negated errno on failure.
 *
 ****************************************************************************/

int sg2000_eth_initialize(void);

#endif /* __VENDOR_SG2000_SG2000_ETH_H */

/****************************************************************************
 * vendor/sg2000/chips/sg2000/sg2000_eth.c
 *
 * SG2000 (CV181x) DWMAC4 Ethernet Driver for OpenVela
 * Implements the netdev_lowerhalf_s architecture per OpenVela spec.
 *
