/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Size of the private DMA buffer used when netpkt is fragmented or we need
 * an intermediate buffer for RX data.
 */

#define SG2000_ETH_BUFSIZE      1600

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct sg2000_eth_priv_s g_eth_priv;

/****************************************************************************
 * Private Functions - Register Access Helpers
 ****************************************************************************/

static inline uint32_t getreg32(uintptr_t addr)
{
  return *(volatile uint32_t *)addr;
}

static inline void putreg32(uint32_t val, uintptr_t addr)
{
  *(volatile uint32_t *)addr = val;
}

/****************************************************************************
 * Private Functions - Hardware Verification
 ****************************************************************************/

static int test_read_hw_feature(uintptr_t gmac_base)
{
  uint32_t feat0 = getreg32(gmac_base + GMAC_HW_FEATURE0);

  ninfo("HW_FEATURE0 = 0x%08" PRIX32 "\n", feat0);
  ninfo("  MII(10/100M): %s\n", (feat0 & (1 << 0)) ? "YES" : "NO");

  if (feat0 == 0x00000000 || feat0 == 0xFFFFFFFF)
    {
      nerr("ERROR: Invalid HW_FEATURE0 value, base address wrong?\n");
      return -1;
    }

  return 0;
}

/****************************************************************************
 * Private Functions - DMA Software Reset
 ****************************************************************************/

static int dma_soft_reset(uintptr_t gmac_base)
{
  uint32_t val;
  int timeout = 100000;

  val = getreg32(gmac_base + DMA_BUS_MODE);
  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);

  do
    {
      val = getreg32(gmac_base + DMA_BUS_MODE);
      if (!(val & DMA_SFT_RESET))
        {
          return 0;
        }

      up_udelay(10);
    }
  while (--timeout > 0);

  nerr("ERROR: DMA reset timeout\n");
  return -1;
}

/****************************************************************************
 * Private Functions - EPHY Reset and MDIO
 ****************************************************************************/

static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
{
  /* Select APB interface */

  putreg32(0x0001, phy_top + 0x4);

  /* Release shutdown */

  putreg32(0x0900, phy_top);

  /* Release dig_rst_n */

  putreg32(0x0904, phy_top);

  /* Switch to Page 5 */

  putreg32(0x0500, phy_base + 0x7c);

  /* ANA_PD */

  putreg32(0x0c00, phy_base + 0x40);

  /* ANA_EN */

  putreg32(0x0c7e, phy_base + 0x40);
  up_mdelay(1);

  /* Release ana_rst_n */

  putreg32(0x0906, phy_top);
  putreg32(0x0500, phy_base + 0x7c);

  /* Set PHY ID */

  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */

  /* Switch back to MDIO control */

  putreg32(0x0000, phy_top + 0x4);
  up_mdelay(10);
}

static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
{
  uint32_t val;
  int timeout = 10000;

  val = ((phy_addr & 0x1f) << 11) | ((reg & 0x1f) << 6) | 0x1;
  putreg32(val, gmac_base + GMAC_MDIO_ADDR);

  do
    {
      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
      if (!(val & 0x1))
        {
          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  return 0xffff;
}

static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
                       uint16_t data)
{
  int timeout = 10000;

  putreg32(data, gmac_base + GMAC_MDIO_DATA);
  putreg32(((phy_addr & 0x1f) << 11) | ((reg & 0x1f) << 6) |
           GMAC_MDIO_WRITE | 0x1,
           gmac_base + GMAC_MDIO_ADDR);

  do
    {
      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & 0x1))
        {
          break;
        }

      up_udelay(1);
    }
  while (--timeout > 0);
}

/****************************************************************************
 * Private Functions - PHY Configuration
 ****************************************************************************/

static int phy_config_init(struct sg2000_eth_priv_s *priv)
{
  uint16_t bmsr;
  uint16_t bmcr;
  int timeout;

  /* Read PHY ID */

  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
  uint32_t phy_id = (id1 << 16) | id2;

  ninfo("PHY ID = 0x%08" PRIX32 " (expect 0x00435649)\n", phy_id);

  if (phy_id == 0xffffffff)
    {
      nerr("ERROR: PHY not responding\n");
      return -1;
    }

  if (phy_id != CVITEK_PHY_ID)
    {
      nwarn("WARNING: Unexpected PHY ID 0x%08" PRIX32 "\n", phy_id);
    }

  /* Reset PHY */

  mdio_write(priv->gmac_base, 0, 0, 0x8000);
  up_mdelay(10);

  timeout = 100;
  do
    {
      bmcr = mdio_read(priv->gmac_base, 0, 0);
      if (!(bmcr & 0x8000))
        {
          break;
        }

      up_mdelay(1);
    }
  while (--timeout > 0);

  /* Read basic status */

  bmsr = mdio_read(priv->gmac_base, 0, 1);
  ninfo("PHY BMSR = 0x%04X\n", bmsr);

  if (!(bmsr & 0x0004))
    {
      nerr("ERROR: PHY link down\n");
      priv->link_up = 0;
      return -ENOTCONN;
    }

  /* Advertise 10/100 Full Duplex */

  mdio_write(priv->gmac_base, 0, 4, 0x01e1);

  /* Start auto-negotiation */

  bmcr = mdio_read(priv->gmac_base, 0, 0);
  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
  up_mdelay(100);

  /* Check result */

  bmsr = mdio_read(priv->gmac_base, 0, 1);
  if (bmsr & 0x0020)
    {
      uint16_t anlpar = mdio_read(priv->gmac_base, 0, 5);
      ninfo("PHY ANLPAR = 0x%04X\n", anlpar);

      priv->speed = 100;
      priv->duplex = 1;  /* Full */
    }
  else
    {
      priv->speed = 10;
      priv->duplex = 1;  /* Full */
    }

  priv->link_up = 1;
  ninfo("PHY link up: %d Mbps %s duplex\n", priv->speed,
        priv->duplex ? "Full" : "Half");
  return 0;
}

/****************************************************************************
 * Private Functions - DMA Descriptor Management
 ****************************************************************************/

static int alloc_dma(struct sg2000_eth_priv_s *priv)
{
  int i;

  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
                                sizeof(struct sg2000_dma_desc_s));
  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
                                sizeof(struct sg2000_dma_desc_s));

  if (!priv->tx_desc || !priv->rx_desc)
    {
      return -ENOMEM;
    }

  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));

  /* For MMU-less or identity-mapped platforms, virtual address = physical.
   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
   */

  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;

  for (i = 0; i < TX_RING_SIZE; i++)
    {
      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
      if (!priv->tx_buf[i])
        {
          return -ENOMEM;
        }

      priv->tx_pkt[i] = NULL;
    }

  for (i = 0; i < RX_RING_SIZE; i++)
    {
      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
      if (!priv->rx_buf[i])
        {
          return -ENOMEM;
        }
    }

  return 0;
}

static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t base = priv->gmac_base;
  uintptr_t dma = base + DMA_CHAN_BASE;
  int i;

  /* Initialize TX descriptors */

  for (i = 0; i < TX_RING_SIZE; i++)
    {
      priv->tx_desc[i].des0 = 0;
      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
      priv->tx_pkt[i] = NULL;
    }

  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write) */

  for (i = 0; i < RX_RING_SIZE; i++)
    {
      priv->rx_desc[i].des0 = DESC_OWN;
      priv->rx_desc[i].des1 = RX_BUF_SIZE;
      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
    }

  priv->tx_cur = 0;
  priv->tx_dirty = 0;
  priv->rx_cur = 0;

  /* Program DMA registers */

  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
}

/****************************************************************************
 * Private Functions - MAC and DMA Control
 ****************************************************************************/

static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
{
  uint32_t hi;
  uint32_t lo;

  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];

  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
}

static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
{
  uintptr_t gmac_base = priv->gmac_base;
  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
  uint32_t v;

  /* Configure MAC based on PHY negotiation results */

  v = GMAC_CORE_INIT;
  if (priv->speed == 100)
    {
      v |= GMAC_CONFIG_FES;   /* 100M */
    }

  if (priv->duplex)
    {
      v |= GMAC_CONFIG_DM;    /* Full duplex */
    }

  putreg32(v, gmac_base + GMAC_CONFIG);

  /* Packet filter: pass multicast + broadcast + unicast to us */

  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
           gmac_base + GMAC_PACKET_FILTER);

  /* Enable MAC interrupts */

  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);

  /* Enable MAC TX and RX */

  v = getreg32(gmac_base + GMAC_CONFIG);
  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);

  /* Start TX DMA */

  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);

  /* Start RX DMA */

  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
}

/****************************************************************************
 * Private Functions - Doorbell Helpers
 ****************************************************************************/

static void tx_doorbell(struct sg2000_eth_priv_s *priv)
{
  uint32_t tail = priv->tx_desc_phys +
                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);

  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
}

static void rx_doorbell(struct sg2000_eth_priv_s *priv)
{
  uint32_t tail = priv->rx_desc_phys +
                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);

  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
}

/****************************************************************************
 * Private Functions - Hardware Transmit
 ****************************************************************************/

static int hw_transmit(struct sg2000_eth_priv_s *priv,
                       const uint8_t *data, int len)
{
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
  irqstate_t flags;

  /* Check if the ring is full */

  if (desc->des0 & DESC_OWN)
    {
      return -EBUSY;
    }

  /* Copy data to DMA TX buffer */

  memcpy(priv->tx_buf[idx], data, len);

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
  desc->des1 = len;

  /* OWN | First Segment | Last Segment | Interrupt on Completion */

  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
               (len & RX_DESC_FL_MASK);

  flags = irq_save();
  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  /* Memory barrier: ensure descriptor is visible to DMA engine */

  __asm__ volatile ("fence w,w" ::: "memory");

  tx_doorbell(priv);
  irq_restore(flags);

  return 0;
}

/****************************************************************************
 * Private Functions - TX Cleanup (called from ISR on TX complete)
 ****************************************************************************/

static void tx_cleanup(struct sg2000_eth_priv_s *priv)
{
  irqstate_t flags = irq_save();

  while (priv->tx_dirty != priv->tx_cur)
    {
      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];

      if (desc->des0 & DESC_OWN)
        {
          /* Still owned by DMA, stop */

          break;
        }

      /* Check for TX errors */

      if (desc->des0 & TX_DESC_ES)
        {
          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
        }

      /* Free the netpkt if we have one tracked for this slot */

      if (priv->tx_pkt[priv->tx_dirty] != NULL)
        {
          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
          priv->tx_pkt[priv->tx_dirty] = NULL;

          /* Notify upper half that TX is done */

          netdev_lower_txdone(&priv->dev);
        }

      /* Move to next descriptor */

      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
    }

  irq_restore(flags);
}

/****************************************************************************
 * Private Functions - ISR
 ****************************************************************************/

static int sg2000_eth_isr(int irq, void *context, void *arg)
{
  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
  uintptr_t base = priv->gmac_base;
  uintptr_t dma = base + DMA_CHAN_BASE;
  uint32_t status;
  uint32_t intr_en;
  uint32_t mac;

  /* Clear MAC interrupts */

  mac = getreg32(base + GMAC_INT_STATUS);
  if (mac)
    {
      putreg32(mac, base + GMAC_INT_STATUS);
    }

  /* Read DMA channel status (only enabled interrupts) */

  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;

  if (!status)
    {
      return OK;
    }

  /* Write-1-to-clear the status bits */

  putreg32(status, dma + DMA_CHAN_STATUS);

  if (status & DMA_STATUS_NIS)
    {
      /* Normal interrupt */

      if (status & DMA_STATUS_RI)
        {
          /* RX complete: notify upper half that packets are ready.
           * The upper half will call our receive() callback to get them.
           */

          netdev_lower_rxready(&priv->dev);
        }

      if (status & DMA_STATUS_TI)
        {
          /* TX complete: cleanup descriptors and notify upper half */

          tx_cleanup(priv);
        }
    }

  if (status & DMA_STATUS_AIS)
    {
      /* Abnormal interrupt */

      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);

      if (status & DMA_STATUS_RBU)
        {
          nerr("ERROR: RX Buffer Unavailable\n");
        }

      if (status & DMA_STATUS_TPS)
        {
          nerr("ERROR: TX Process Stopped\n");
        }

      if (status & DMA_STATUS_FBE)
        {
          nerr("ERROR: Fatal Bus Error\n");
        }
    }

  return OK;
}

/****************************************************************************
 * Name: netdriver_ifup
 *
 * Description:
 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
 *
 ****************************************************************************/

static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  int ret;

  ephy_hardware_reset(priv->phy_base, priv->phy_top);
  up_mdelay(10);

  ret = phy_config_init(priv);
  if (ret < 0)
    {
      nerr("ERROR: PHY init failed: %d\n", ret);
      return ret;
    }

  if (!priv->link_up)
    {
      nerr("ERROR: PHY link not up\n");
      return -ENOTCONN;
    }

  dma_soft_reset(priv->gmac_base);
  init_desc_and_dma(priv);
  set_mac_addr(priv->gmac_base, priv->mac_addr);
  start_mac_and_dma(priv);
  rx_doorbell(priv);

  up_enable_irq(priv->irq);
  netdev_lower_carrier_on(dev);

  ninfo("netdriver_ifup: interface up, %d Mbps %s duplex\n",
        priv->speed, priv->duplex ? "Full" : "Half");

  return OK;
}

/****************************************************************************
 * Name: netdriver_ifdown
 *
 * Description:
 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
 *
 ****************************************************************************/

static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  uint32_t v;

  up_disable_irq(priv->irq);

  /* Stop TX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
  putreg32(v & ~DMA_TX_ST,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);

  /* Stop RX DMA */

  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
  putreg32(v & ~DMA_RX_SR,
           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);

  /* Disable MAC TX/RX */

  v = getreg32(priv->gmac_base + GMAC_CONFIG);
  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
           priv->gmac_base + GMAC_CONFIG);

  netdev_lower_carrier_off(dev);

  ninfo("netdriver_ifdown: interface down\n");

  return OK;
}

/****************************************************************************
 * Name: netdriver_transmit
 *
 * Description:
 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
 *   The driver takes ownership of the netpkt and MUST free it after TX
 *   completion (or on error).
 *
 *   Returned Value:
 *     OK on success (pkt queued for TX); negated errno on failure.
 *
 ****************************************************************************/

static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
                               FAR netpkt_t *pkt)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  unsigned int len = netpkt_getdatalen(dev, pkt);
  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
  const uint8_t *data;
  int ret;

  if (len > SG2000_ETH_BUFSIZE)
    {
      nerr("ERROR: TX packet too large: %u\n", len);
      netpkt_free(dev, pkt, NETPKT_TX);
      return -E2BIG;
    }

  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */

  if (netpkt_is_fragmented(pkt))
    {
      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
      data = tmp_buf;
    }
  else
    {
      data = netpkt_getdata(dev, pkt);
      if (!data)
        {
          nerr("ERROR: netpkt_getdata returned NULL\n");
          netpkt_free(dev, pkt, NETPKT_TX);
          return -EINVAL;
        }
    }

  /* Send via DMA */

  ret = hw_transmit(priv, data, len);
  if (ret < 0)
    {
      nerr("ERROR: hw_transmit failed: %d\n", ret);
      netpkt_free(dev, pkt, NETPKT_TX);
      return ret;
    }

  /* Track this packet: store it so tx_cleanup can free it after DMA done.
   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
   */

  {
    irqstate_t flags = irq_save();
    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);

    priv->tx_pkt[slot] = pkt;
    irq_restore(flags);
  }

  return OK;
}

/****************************************************************************
 * Name: netdriver_receive
 *
 * Description:
 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
 *   NULL if no more packets are available.
 *
 *   Returned Value:
 *     A netpkt_t * containing the received packet, or NULL.
 *
 ****************************************************************************/

static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct sg2000_eth_priv_s *priv =
      (FAR struct sg2000_eth_priv_s *)dev;
  FAR netpkt_t *pkt;
  struct sg2000_dma_desc_s *desc;
  uint32_t status;
  int frame_len;
  int ret;

  /* Check if there is a completed RX descriptor */

  desc = &priv->rx_desc[priv->rx_cur];
  if (desc->des0 & DESC_OWN)
    {
      /* DMA still owns it, no packet ready yet.
       * This can happen if rxready was signaled for a previous packet
       * that was already consumed, or in edge cases.
       */

      return NULL;
    }

  status = desc->des0;

  /* Check for errors */

  if (status & RX_DESC_ES)
    {
      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
      goto refill;
    }

  /* Get frame length (includes FCS which we strip) */

  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;

  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
    {
      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
      goto refill;
    }

  /* Allocate a netpkt for the received data */

  pkt = netpkt_alloc(dev, NETPKT_RX);
  if (!pkt)
    {
      nerr("ERROR: netpkt_alloc failed\n");
      goto refill;
    }

  /* Copy data from DMA RX buffer into the netpkt */

  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
  if (ret < 0)
    {
      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
      netpkt_free(dev, pkt, NETPKT_RX);
      goto refill;
    }

  ninfo("RX packet: %d bytes\n", frame_len);

refill:
  /* Return the descriptor to DMA (set OWN=1) */

  desc->des0 = DESC_OWN;
  desc->des1 = RX_BUF_SIZE;

  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
  rx_doorbell(priv);

  return pkt;
}

/****************************************************************************
 * Private Data - Operations Structure
 *
 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
 ****************************************************************************/

static const struct netdev_ops_s g_ops =
{
  netdriver_ifup,     /* ifup */
  netdriver_ifdown,   /* ifdown */
  netdriver_transmit, /* transmit */
  netdriver_receive   /* receive */
  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
   * filtering scenarios.
   */
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sg2000_eth_initialize
 *
 * Description:
 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
 *   network stack as a netdev_lowerhalf_s device.
 *
 *   Called from board_late_initialize() during system bringup.
 *
 ****************************************************************************/

int sg2000_eth_initialize(void)
{
  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
  int ret;
  uint32_t r1;
  uint32_t r2;

  memset(priv, 0, sizeof(*priv));
  priv->gmac_base = SG2000_GMAC_BASE;
  priv->phy_base = SG2000_EPHY_BASE;
  priv->phy_top = SG2000_EPHY_TOP;

  /* Set a test MAC address (should be replaced with eFuse/OTP value) */

  priv->mac_addr[0] = 0x02;
  priv->mac_addr[1] = 0x00;
  priv->mac_addr[2] = 0x00;
  priv->mac_addr[3] = 0x00;
  priv->mac_addr[4] = 0x00;
  priv->mac_addr[5] = 0x01;

  /* Step 1: Verify hardware register readability */

  ret = test_read_hw_feature(priv->gmac_base);
  if (ret < 0)
    {
      nerr("ERROR: HW feature test failed\n");
      return ret;
    }

  ninfo("HW feature register test PASS\n");

  /* Step 2: DMA software reset */

  ret = dma_soft_reset(priv->gmac_base);
  if (ret < 0)
    {
      nerr("ERROR: DMA reset failed\n");
      return ret;
    }

  ninfo("DMA reset PASS\n");

  /* Step 3: EPHY reset and PHY ID verification */

  ephy_hardware_reset(priv->phy_base, priv->phy_top);

  {
    uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
    uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
    uint32_t phy_id = (id1 << 16) | id2;

    ninfo("PHY ID = 0x%08" PRIX32 " (expect 0x00435649)\n", phy_id);

    if (phy_id == 0xffffffff)
      {
        nerr("ERROR: PHY not responding\n");
        return -1;
      }
  }

  ninfo("PHY ID verification PASS\n");

  /* Step 4: Allocate DMA descriptor rings and buffers */

  ret = alloc_dma(priv);
  if (ret < 0)
    {
      nerr("ERROR: alloc_dma failed: %d\n", ret);
      return ret;
    }

  init_desc_and_dma(priv);

  /* Readback verification of DMA registers */

  r1 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_BASE_ADDR);
  r2 = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_RING_LEN);

  ninfo("Readback TX_BASE: 0x%08" PRIX32 " (expect 0x%08" PRIX32 ") %s\n",
        r1, priv->tx_desc_phys,
        r1 == priv->tx_desc_phys ? "OK" : "FAIL");
  ninfo("Readback TX_LEN:  %" PRIu32 " (expect %d) %s\n",
        r2, TX_RING_SIZE - 1,
        r2 == (TX_RING_SIZE - 1) ? "OK" : "FAIL");

  if (r1 != priv->tx_desc_phys || r2 != (TX_RING_SIZE - 1))
    {
      nerr("ERROR: DMA register readback mismatch\n");
      return -1;
    }

  ninfo("DMA descriptor setup PASS\n");

  /* Step 5: Initialize PHY and establish link */

  ret = phy_config_init(priv);
  if (ret < 0 || !priv->link_up)
    {
      nerr("ERROR: PHY not linked\n");
      return -ENOTCONN;
    }

  /* Step 6: Configure MAC and start DMA */

  set_mac_addr(priv->gmac_base, priv->mac_addr);
  start_mac_and_dma(priv);
  rx_doorbell(priv);

  /* Step 7: Register ISR */

  priv->irq = SG2000_IRQ_GMAC;
  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
  if (ret < 0)
    {
      nerr("ERROR: irq_attach failed: %d\n", ret);
      return ret;
    }

  up_enable_irq(priv->irq);

  ninfo("IRQ %d enabled\n", priv->irq);

  /* Step 8: Copy MAC address to the netdev */

  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
         IFHWADDRLEN);

  /* Step 9: Set up the lowerhalf device and register with the network stack.
   *
   * Per OpenVela spec (net_driver_guide.md):
   *   - quota: max number of buffers driver can hold simultaneously.
   *     Set to TX_RING_SIZE/2 to allow some concurrency without exhausting.
   *   - ops: pointer to the operations table.
   */

  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
  dev->ops              = &g_ops;

  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
  if (ret < 0)
    {
      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
      return ret;
    }

  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");

  return OK;
}

/****************************************************************************
 * Name: riscv_netinitialize
 *
 * Description:
 *   Arch-level network initialization called from up_initialize().
 *   Initializes the SG2000 Ethernet driver.
 *
 ****************************************************************************/

void riscv_netinitialize(void)
{
  sg2000_eth_initialize();
}

